                    if (r + dy, c) not in cells or (r, c + dx) not in cells:
                        continue
                    vl = hl = 0
                    while (r + (vl + 1) * dy, c) in cells:
                        vl += 1
                    while (r, c + (hl + 1) * dx) in cells:
                        hl += 1
                    candidates.append((vl + hl, len(cells), color, r, c, dy, dx))

    if not candidates:
        return [row[:] for row in grid]

    _, _, pointer_color, r0, c0, dy, dx = max(candidates)
    sy, sx = -dy, -dx

    # The target is the nearest non-background object in the open quadrant.
    targets = []
    for color, cells in comps:
        if color == pointer_color:
            continue
        hits = [(r, c) for r, c in cells
                if (r - r0) * sy > 0 and (c - c0) * sx > 0]
        if hits:
            dist = min(abs(r - r0) + abs(c - c0) for r, c in hits)
            targets.append((dist, cells))

    if not targets:
        return [row[:] for row in grid]

    target = min(targets, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = pointer_color
    return out
